<template>
 <section class="container py-4 email-activity">
  <header><p class="eyebrow">Superadmin</p><h1>{{ tr('Actividad de correo','Email activity') }}</h1><p>{{ tr('Invitaciones y solicitudes de contraseña de todas las iglesias.','Invitations and password requests across churches.') }}</p></header>
  <form class="filters" @submit.prevent="load(1)"><label>{{ tr('Desde','From') }}<input v-model="filters.from" type="date" class="form-control" /></label><label>{{ tr('Hasta','To') }}<input v-model="filters.to" type="date" :min="filters.from || undefined" class="form-control" /></label><label>{{ tr('Estado','Status') }}<select v-model="filters.status" class="form-select"><option value="">{{ tr('Todos','All') }}</option><option value="accepted">{{ tr('Aceptado','Accepted') }}</option><option value="failed">{{ tr('Fallido','Failed') }}</option><option value="throttled">{{ tr('Limitado','Throttled') }}</option></select></label><button class="btn btn-primary" :disabled="loading">{{ tr('Consultar','Search') }}</button></form>
  <p class="note">{{ tr('Aceptado significa que el proveedor recibió la solicitud; no confirma la entrega. Solo se registran correos de invitación y recuperación enviados desde esta actualización. Los enlaces y contraseñas no se guardan.','Accepted means the provider received the request; delivery is not confirmed. Only invitations and password recovery emails sent since this update are recorded. Links and passwords are not stored.') }}</p>
  <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="loading" role="status">{{ tr('Cargando…','Loading…') }}</p>
  <div v-else class="activity-list"><p v-if="!items.length" class="empty">{{ tr('No hay actividad para mostrar.','No activity to display.') }}</p><article v-for="item in items" :key="item.id" class="activity-card"><div><strong>{{ item.recipient_email }}</strong><span>{{ item.church_name || tr('Sin iglesia','No church') }}</span></div><div><span>{{ tr('Tipo','Type') }}</span><strong>{{ item.kind==='invitation' ? tr('Invitación','Invitation') : tr('Contraseña','Password reset') }}</strong></div><div><span>{{ tr('Solicitado por','Requested by') }}</span><strong>{{ item.actor_name || tr('Usuario desde inicio de sesión','User from login') }}</strong></div><div><span>{{ tr('Fecha','Date') }}</span><strong>{{ formatDate(item.created_at) }}</strong></div><div><span>{{ tr('Estado','Status') }}</span><strong :class="'status-'+item.status">{{ statusLabel(item.status) }}</strong></div></article></div>
  <nav v-if="lastPage>1" class="pager"><button class="btn btn-outline-secondary" :disabled="loading||page<=1" @click="load(page-1)">{{ tr('Anterior','Previous') }}</button><span>{{ page }} / {{ lastPage }}</span><button class="btn btn-outline-secondary" :disabled="loading||page>=lastPage" @click="load(page+1)">{{ tr('Siguiente','Next') }}</button></nav>
 </section>
</template>
<script setup>
import {onMounted,reactive,ref} from 'vue'
import {apiClient} from '../../services/authApi'
import {useUiStore} from '../../stores/uiStore'
const ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const filters=reactive({from:'',to:'',status:''}),items=ref([]),page=ref(1),lastPage=ref(1),loading=ref(false),error=ref('')
const statusLabel=status=>({accepted:tr('Aceptado','Accepted'),failed:tr('Fallido','Failed'),throttled:tr('Limitado','Throttled'),simulated:tr('Simulado (no enviado)','Simulated (not sent)')})[status]||status
const formatDate=value=>{const parsed=new Date(value.endsWith('Z')?value:value.replace(' ','T')+'Z');return Number.isNaN(parsed.getTime())?value:parsed.toLocaleString(ui.locale==='es'?'es':'en')}
async function load(next){loading.value=true;error.value='';try{const {data}=await apiClient.get('/superadmin/email-activity',{params:{...filters,page:next}});items.value=data.data;page.value=data.current_page;lastPage.value=data.last_page}catch{error.value=tr('No se pudo cargar la actividad de correo.','Unable to load email activity.')}finally{loading.value=false}}
onMounted(()=>load(1))
</script>
<style scoped>
.email-activity{min-width:0;color:#243e32}.email-activity h1{font-size:23px}.email-activity header p{color:#617268}.eyebrow{color:#1f6f5c!important;font-size:12px;font-weight:600}.filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;padding:16px;background:white;border:1px solid #dce5df;border-radius:10px}.filters label{display:grid;gap:5px;flex:1 1 150px;font-size:12px}.filters .btn{width:auto;background:#1f6f5c;border-color:#1f6f5c}.note{margin:16px 0;color:#53685a;font-size:12px}.activity-list{display:grid;gap:10px}.activity-card{min-width:0;display:grid;grid-template-columns:2fr 1fr 1.4fr 1.4fr 1fr;gap:14px;padding:16px;background:#fff;border:1px solid #dce5df;border-radius:10px}.activity-card div{min-width:0;display:grid;gap:4px}.activity-card span{font-size:12px;color:#687a6d}.activity-card strong{font-size:13px;font-weight:500;overflow-wrap:anywhere}.status-accepted{color:#23734e}.status-failed{color:#a33c37}.status-throttled{color:#8b6217}.pager{display:flex;gap:12px;align-items:center;justify-content:center;margin-top:18px}.pager button{width:auto}.empty{text-align:center;padding:20px}@media(max-width:850px){.activity-card{grid-template-columns:repeat(2,minmax(0,1fr))}.activity-card div:first-child{grid-column:1/-1}}@media(max-width:480px){.activity-card{grid-template-columns:1fr}.activity-card div:first-child{grid-column:auto}}
</style>
